ALTER TABLE hearth_economy.version DROP CONSTRAINT version_version_check;
ALTER TABLE hearth_economy.version ADD CONSTRAINT version_version_check CHECK(version BETWEEN 1 AND 10);
CREATE TABLE hearth_economy.extra_world(realm_id uuid REFERENCES hearth_economy.native_binding,role text CHECK(role IN ('novice','end')),world_key text NOT NULL,world_uuid uuid NOT NULL UNIQUE,seed bigint NOT NULL,PRIMARY KEY(realm_id,role));
CREATE TABLE hearth_economy.house_pvp(realm_id uuid NOT NULL,house_id uuid NOT NULL,enabled boolean NOT NULL,revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),PRIMARY KEY(realm_id,house_id),FOREIGN KEY(realm_id,house_id) REFERENCES hearth_economy.house);
CREATE TABLE hearth_economy.player_home(realm_id uuid NOT NULL,player_uuid uuid NOT NULL,world_uuid uuid NOT NULL,x double precision NOT NULL,y double precision NOT NULL,z double precision NOT NULL,yaw real NOT NULL,pitch real NOT NULL,revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),PRIMARY KEY(realm_id,player_uuid),FOREIGN KEY(realm_id,player_uuid) REFERENCES hearth_economy.account);
CREATE TABLE hearth_economy.object_acl(realm_id uuid NOT NULL REFERENCES hearth_economy.native_binding,id uuid NOT NULL,owner_uuid uuid NOT NULL,world_uuid uuid NOT NULL,x integer NOT NULL,y integer NOT NULL,z integer NOT NULL,x2 integer NOT NULL,y2 integer NOT NULL,z2 integer NOT NULL,mode text NOT NULL CHECK(mode IN ('PRIVATE','PUBLIC','LIST','REMOVED')),allowed uuid[] NOT NULL,revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),PRIMARY KEY(realm_id,id),UNIQUE(realm_id,world_uuid,x,y,z),FOREIGN KEY(realm_id,owner_uuid) REFERENCES hearth_economy.account);
CREATE TABLE hearth_economy.skill_cooldown(realm_id uuid NOT NULL,player_uuid uuid NOT NULL,skill_id text NOT NULL,until_millis bigint NOT NULL CHECK(until_millis>0),PRIMARY KEY(realm_id,player_uuid,skill_id),FOREIGN KEY(realm_id,player_uuid) REFERENCES hearth_economy.account);
